#include "stdafx.h"
#include <fstream.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINES 1000
#define MAX_TOKENS 7
#define MAX_TOKEN_LENGTH 10
#define MAX_VARS 100
#define MAX_VAR_LENGTH 10

#define GET_TOKEN \
	infile >> token; \
	strcpy(lines[currentLineNum][currentToken++], token);

#define FIND_VAR \
	varFound = false; \
	for (i = 0; i < numVars; i++) \
	{ \
		if (!strcmp(lines[currentLineNum][currentToken+1], varNames[i])) \
		{ \
			varFound = true; \
			break; \
		} \
	}

int main(int argc, char* argv[])
{
	char varNames[MAX_VARS][MAX_VAR_LENGTH + 1];
	int varValues[MAX_VARS];
	char lines[MAX_LINES][MAX_TOKENS][MAX_TOKEN_LENGTH + 1];
	char token[MAX_TOKEN_LENGTH + 1];
	int currentLineNum = 0;
	int currentToken = 0;
	int numVars = 0;
	int currentDataSet = 1;
	int i = 0;
	bool varFound = false;
	ifstream infile;

	infile.open("computer.dat");
	//Reset variables
	memset(&varValues, 0, MAX_VARS * sizeof(int));
	currentLineNum = 0;
	currentToken = 0;
	numVars = 0;

	//Read in the first line number
	GET_TOKEN;

	while (infile)
	{
		GET_TOKEN;

		while(strcmp(token, "END"))
		{
			if (!strcmp(token, "LOAD") || !strcmp(token, "ADD"))
			{
				GET_TOKEN;
				GET_TOKEN;
			}
			else if (!strcmp(token, "PRINT"))
			{
				GET_TOKEN;
			}
			else if (!strcmp(token, "IF"))
			{
				GET_TOKEN;
				GET_TOKEN;
				GET_TOKEN;
				GET_TOKEN;
				GET_TOKEN;
			}
			currentLineNum++;
			currentToken = 0;
			GET_TOKEN;
			GET_TOKEN;
		}
		//Execute program
		currentLineNum = 0;
		currentToken = 1;
		cout << "START " << currentDataSet << endl;

		while (strcmp(lines[currentLineNum][currentToken], "END"))
		{
			if (!strcmp(lines[currentLineNum][currentToken], "LOAD"))	
			{
				FIND_VAR;

				if (!varFound)
					strcpy(varNames[numVars++], lines[currentLineNum][currentToken+1]);

				varValues[i] = atoi(lines[currentLineNum][currentToken+2]);
				currentLineNum++;
			}
			else if (!strcmp(lines[currentLineNum][currentToken], "ADD"))
			{
				FIND_VAR;

				if (!varFound)
					strcpy(varNames[numVars++], lines[currentLineNum][currentToken+1]);

				varValues[i] += atoi(lines[currentLineNum][currentToken+2]);
				currentLineNum++;
			}
			else if (!strcmp(lines[currentLineNum][currentToken], "PRINT"))
			{
				FIND_VAR;

				cout << varValues[i] << endl;
				currentLineNum++;
			}
			else if (!strcmp(lines[currentLineNum][currentToken], "IF"))
			{
				FIND_VAR;

				if (varValues[i] == atoi(lines[currentLineNum][currentToken+3]))
				{
					for (i = 0; i < MAX_LINES; i++)
						if (!strcmp(lines[currentLineNum][currentToken+5],lines[i][0]))
							break;

					currentLineNum = i;
				}
				else
					currentLineNum++;
			}

			currentToken = 1;
		}
		//Reset variables
		memset(&varValues, 0, MAX_VARS * sizeof(int));
		currentLineNum = 0;
		currentToken = 0;
		numVars = 0;
		currentDataSet++;

		//Read in the first line number
		GET_TOKEN;
		
	}

	infile.close();
	return 0;
}

#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 80

int mypow(int base, int exp);

int
main (void)
{
   FILE *infile;

   /* open the input data file */
   infile = fopen("decrypt.dat","r");

   /* process the data sets */
   while (1)
   {
      int args_read;
      int num_encoded_bytes;

      /* read the next start line */
      args_read = fscanf(infile," MESSAGE %d",&num_encoded_bytes);

      /* if there wasn't one, we're done */
      if (args_read != 1) break;

      /* echo the start line */
      printf("MESSAGE %d\n",num_encoded_bytes);

      /* process the message */
      for (int curline=0; curline<((num_encoded_bytes-1)/8+1); curline++)
      {
         char line[MAX_LINE+1];

         /* read the next line of the message */
         fscanf(infile,"%s",line);

         /* print the output */
         for (int curbyte=0; curbyte < (strlen(line)/8); curbyte++)
         {
            char bytevalue=0;

            /* calculate the next byte */
            for (int curbit=0; curbit < 8; curbit++)
            {
               bytevalue+=mypow(2,7-curbit)*(line[(curbyte*8)+curbit]-'0');
            }

            /* print the next byte */
            printf("%c",bytevalue);
         }
      }

      /* End the output line */
      puts("");
   }

   /* return */
   return 0;
}

// subroutine: mypow
//
// This routine was created as an alternative to the regular pow() routine
// since we want to deal only with integer values. 
int
mypow(int base, int exp)
{
   int val = 1;
   for (int i=0; i<exp; i++)
   {
      val*=base;
   } 
   return val;
}

// fraction.cpp : Defines the entry point for the console application.
//

#include "stdafx.h"
#include <fstream.h>

int main(int argc, char* argv[])
{
	int numerator, denominator, i, GPCD;
	bool reducing;
	ifstream infile;

	infile.open("fraction.dat");

	//Read in the first fraction
	infile >> numerator >> denominator;

	while (infile)
	{
		if (numerator < 1 || numerator > 10000)
		{
			cout << "INVALID DATA SET; numerator = " << numerator << endl;
			return 1;
		}
		if (denominator < 1 || denominator > 10000)
		{
			cout << "INVALID DATA SET; denominator = " << denominator << endl;
			return 1;
		}
		if (numerator == denominator)
		{
			//Well, that was easy, the fraction reduces to 1 1
			cout << "1 1" << endl;
		}
		else
		{
			reducing = true;

			while (reducing)
			{
				reducing = false;
				//We'll keep looking for common denominators until we
				//reach half the larger of the numerator and denominator
				//(greatest possible common denominator)
				GPCD = (numerator > denominator) ? numerator / 2 : denominator / 2;
				for (i = 2; i <= GPCD && !reducing; i++)
				{
					if (numerator % i == 0 && denominator % i == 0)
					{
						//We found a common denominator.  Reduce the
						//numerator and denominator and try to reduce
						//some more.
						numerator /= i;
						denominator /= i;
						reducing = true;
					}
				}
			}

			//Display the reduced fraction
			cout << numerator << " " << denominator << endl;
		}
		//Read in the next fraction
		infile >> numerator >> denominator;
	}

	infile.close();
	return 0;
}

